"""Derive SkyyHud/build_skyyhud_0.3.27.py from the LIVE SkyyHud 0.3.26 (build_skyyhud_0.3.26.py = the tools/deploy_set.py SET pin, generated by
tools/hud_0_3_26_patch.py - never edit a generated script, edit this patch). Every anchor is asserted; at the end every change is undone on a
copy and compared with 0.3.26 (nothing else changed). Line endings kept.
Run:  python tools/hud_0_3_27_patch.py   then   python SkyyHud/build_skyyhud_0.3.27.py   (never --deploy)
Check: python SkyyHud/test_skyyhud_0.3.27.py [--dir <folder inside tools/dev/scratch/>] [--keep]

0.3.27 (2026-10-15) = the first-join page fix, the SkyyHud part. Skyy 2026-10-15 (new world): the SkyyProfiles "CREATE YOUR FIRST
PROFILE" page drew washed out / flickering white / see-through with item icons inside the buttons until hovered ("it loaded better after
hovering over everything", "clicked select and its all good now"). The live logs: 0.3.26 sent the minimap's statics (14 masks + 32 arrows
+ the dark picture) and its ONE RequestCommonAssetsRebuild only at the minimap's first attach - after the world's first REAL map piece,
seconds after the join - so the client repacked its UI texture atlas while the profile page (opened at join) was already on screen and
that page kept pointing at stale atlas spots. Any page open at join (Islands, the Quests tutorial) could break the same way.
  1. EARLY: PlayerConnectEvent (Minimap.hello - before the player is in any world, so before anything can open a page) queues a "hello"
     request; the minimap thread (<= 0.25 s later) sends this connection's statics + the one rebuild right away whenever the minimap is on
     in Server Setup and BetterMap is there - also for a player whose own minimap widget is off (33 small pictures, once per connection),
     so switching the widget on later (from the editor page) needs no rebuild either. The first attach finds them sent (no second rebuild).
     Review fix: the minimap HUD is never shown while this connection's rebuild still waits (attach() -> pending; step() re-runs the
     attach once it went), and a world-thread check whose world stopped before it ran is asked again after 3 s.
  2. NEVER UNDER AN OPEN PAGE: the rebuild is written straight from the minimap thread only while the player has no entity in a world yet
     (no page can exist); otherwise ONE world-thread check (Minimap.rebuild -> MmRebuild -> rebuildCheck on the player's own world, the
     store re-checked to be that world's): no custom page open (PageManager.getCustomPage() == null) = the rebuild goes now; a page open =
     it waits (re-checked every 0.5 s by the minimap tick, one log line) and goes as soon as that page is closed. Chosen over re-sending
     the open page after the rebuild: the server cannot know when the client has finished repacking, and re-opening another mod's page
     instance could run its build twice or lose what was typed - waiting never touches another mod's page.
  3. THE FLAG: skyy.bridge "hud:assets:ready:<uuid>" = Boolean.TRUE (plain java.lang) the moment this connection's rebuild was written -
     at once at connect when no rebuild will come (BetterMap missing, or the minimap off in Server Setup). Removed when a NEW connection of
     that player connects (a fast reconnect never inherits the old flag), at disconnect (only the flag THAT connection set) and at
     shutdown (every flag this jar set) - each time remove(key, Boolean.TRUE), never another value. SkyyProfiles 0.1.15 waits for it.
  No saved-data change, no layout / widget / page / command change. ROLLBACK to 0.3.26: safe (the flag is memory only; SkyyProfiles 0.1.15
  then waits its 12 s fallback for a first-profile page).
"""
import os

ROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
src = os.path.join(ROOT, "SkyyHud", "build_skyyhud_0.3.26.py")
dst = os.path.join(ROOT, "SkyyHud", "build_skyyhud_0.3.27.py")
raw = open(src, encoding="utf8", newline="").read()
CR, LF = chr(13), chr(10)
NL = CR + LF if (CR + LF) in raw else LF
s = raw.replace(CR + LF, LF)
OLD = s
assert 'VERSION = "0.3.26"' in s and "GENERATED by tools/hud_0_3_26_patch.py from the LIVE 0.3.25" in s and "hud:assets:ready" not in s, "not the 0.3.26 script"
CHANGES = []


def rep(old, new):
    global s
    n = s.count(old)
    assert n == 1, "anchor count %d: %s" % (n, old[:160])
    s = s.replace(old, new, 1)
    CHANGES.append((new, old))


HEAD = open(__file__, encoding="utf8").read().split('"""')[1]
NOTE = HEAD[HEAD.index("0.3.27 (2026-10-15)"):].rstrip() + "\n"

# ================================================================================================ docstring + version
rep('''"""SkyyHud 0.3.26 - build script (javassist via jpype). GENERATED by tools/hud_0_3_26_patch.py from the LIVE 0.3.25 - edit the patch.
Run:   python build_skyyhud_0.3.26.py            -> SkyyHud/SkyyHud-0.3.26.jar
       (deploys only through tools/deploy_set.py - never pass --deploy here)
Check: python SkyyHud/test_skyyhud_0.3.26.py
''', '''"""SkyyHud 0.3.27 - build script (javassist via jpype). GENERATED by tools/hud_0_3_27_patch.py from the LIVE 0.3.26 - edit the patch.
Run:   python build_skyyhud_0.3.27.py            -> SkyyHud/SkyyHud-0.3.27.jar
       (deploys only through tools/deploy_set.py - never pass --deploy here)
Check: python SkyyHud/test_skyyhud_0.3.27.py
''' + NOTE + '''0.3.26 (generated by tools/hud_0_3_26_patch.py from 0.3.25):
''')
rep('VERSION = "0.3.26"\n', 'VERSION = "0.3.27"\n')

# ================================================================================================ engine members (API drift fails the build)
rep('''pool.get(MMT["PID"])
''', '''pool.get(MMT["PID"])
# 0.3.27: the picture rebuild waits while a custom page is open (world thread) + the player's world lookup
for c, m in (("com.hypixel.hytale.server.core.entity.entities.player.pages.PageManager", "getCustomPage"), (PLA, "getPageManager"),
             (UNI, "get"), (UNI, "getWorld"), (REF, "getStore"), (REF, "isValid")):
    B.probe(pool, c, m)
''')

# ================================================================================================ the class
rep('''mmquit = pool.makeClass(PKG + ".MmQuit")
''', '''mmquit = pool.makeClass(PKG + ".MmQuit")
mmreb = pool.makeClass(PKG + ".MmRebuild")                 # 0.3.27: the world-thread check before the one picture rebuild
''')
rep('''       mmcfg, mmpng, mmasset, mmsess, mmhud, mmreq, mmmain, mmui, mmtick, mmthr, mmatt, mmdet, mmtap, mmcon, mmquit, cmm, cmmon, cmmoff,
''', '''       mmcfg, mmpng, mmasset, mmsess, mmhud, mmreq, mmmain, mmui, mmtick, mmthr, mmatt, mmdet, mmtap, mmcon, mmquit, mmreb, cmm, cmmon, cmmoff,
''')

# ================================================================================================ MmSess: the per-connection rebuild state
rep('''           "public boolean realSeen;", "public int voids;", "public volatile java.util.UUID tapW;", "public java.util.UUID drainW;"):
    MMF(mmsess, _f)''', '''           "public boolean realSeen;", "public int voids;", "public volatile java.util.UUID tapW;", "public java.util.UUID drainW;",
           # 0.3.27: this connection's one picture rebuild: written (+ when), a world-thread check on its way, the next check, logged once
           "public volatile boolean rbDone;", "public volatile long rbAt;", "public volatile boolean rbAsk;", "public volatile long rbNext;",
           "public volatile boolean rbWaitLogged;",
           # review fix: when the world-thread check was asked (a check whose world stopped before it ran is dropped after 3 s)
           "public volatile long rbAskAt;"):
    MMF(mmsess, _f)''')

# ================================================================================================ MmRebuild: fields + constructor (before the Minimap methods)
rep('''MMC(mmdet, "public MmDetach(@PR@ pr, @ST@ st, @PKG@.MmHud h) { this.pr = pr; this.store = st; this.hud = h; }")
''', '''MMC(mmdet, "public MmDetach(@PR@ pr, @ST@ st, @PKG@.MmHud h) { this.pr = pr; this.store = st; this.hud = h; }")
mmreb.addInterface(pool.get("java.lang.Runnable"))
for _f in ("public @PKG@.MmSess sess;", "public @WLD@ world;"):
    MMF(mmreb, _f)
MMC(mmreb, "public MmRebuild(@PKG@.MmSess s, @WLD@ w) { this.sess = s; this.world = w; }")
''')

# ================================================================================================ Minimap: FLAGGED (uuid -> the PlayerRef whose flag this jar put)
rep('''           "public static final java.util.LinkedList TAIL = new java.util.LinkedList();"):
    MMF(mmmain, _f)''', '''           "public static final java.util.LinkedList TAIL = new java.util.LinkedList();",
           # 0.3.27: uuid -> the connection (PlayerRef) whose hud:assets:ready flag this jar put on skyy.bridge
           "public static final java.util.concurrent.ConcurrentHashMap FLAGGED = new java.util.concurrent.ConcurrentHashMap();"):
    MMF(mmmain, _f)''')

# ================================================================================================ the flag + the rebuild, then statics() calls it
rep('''# the 14 masks (7 sizes x round / square) + 16 arrows + the "not yet" picture go ONCE per connection, then ONE rebuild (critic C14)
MMM(mmmain, r"""
public static void statics(@PKG@.MmSess s) {
  if (STATICS.contains(s.uuid)) return;
  for (int z = 50; z <= 200; z = z + 25) {
    int S = 160 * z / 100;
    int C = S - 2 * Math.max(3, S / 40);
    send(s, gen("mask:" + C + ":0"), false);
    send(s, gen("mask:" + C + ":1"), false);
  }
  for (int k = 0; k < 16; k++) send(s, gen("arrow:" + k), false);
  for (int k = 0; k < 16; k++) send(s, gen("arrowS:" + k), false);
  send(s, gen("dark"), false);
  s.pr.getPacketHandler().writeNoCache(new @ARB@());
  STATICS.add(s.uuid);
}""")''', '''# 0.3.27: skyy.bridge "hud:assets:ready:<uuid>" = Boolean.TRUE once this connection's statics + the one picture rebuild are written (or at
# connect when none will come). FLAGGED remembers WHICH connection put it: a disconnect removes only its own flag (a fast reconnect's newer
# flag stays), a new connection starts unflagged, shutdown removes every flag of this jar - always remove(key, Boolean.TRUE)
MMM(mmmain, "public static String flagKey(java.util.UUID u) { return \\"hud:assets:ready:\\" + u.toString(); }")
MMM(mmmain, r"""
public static void flag(@PR@ pr) {
  if (pr == null) return;
  java.util.UUID u = pr.getUuid();
  if (u == null) return;
  try {
    FLAGGED.put(u, pr);
    @PKG@.FeedCfg.bridgeC().put(flagKey(u), Boolean.TRUE);
  } catch (Throwable t) { err("publishing hud:assets:ready", t); }
}""")
MMM(mmmain, r"""
public static void unflagKey(java.util.UUID u) {
  try {
    Object b = System.getProperties().get("skyy.bridge");
    if (b instanceof java.util.Map) ((java.util.Map) b).remove(flagKey(u), Boolean.TRUE);
  } catch (Throwable t) { }
}""")
MMM(mmmain, r"""
public static void unflag(java.util.UUID u) {
  if (u == null) return;
  FLAGGED.remove(u);
  unflagKey(u);
}""")
MMM(mmmain, r"""
public static void unflagFor(@PR@ pr) {
  if (pr == null) return;
  java.util.UUID u = pr.getUuid();
  if (u == null) return;
  if (FLAGGED.remove(u, pr)) unflagKey(u);
}""")
MMM(mmmain, r"""
public static void unflagAll() {
  Object[] ks = FLAGGED.keySet().toArray();
  for (int i = 0; i < ks.length; i++) unflag((java.util.UUID) ks[i]);
}""")
# the one RequestCommonAssetsRebuild of a connection (any thread: the minimap thread or the player's world thread), then the flag
MMM(mmmain, r"""
public static void rebuildSend(@PKG@.MmSess s, String when) {
  if (s.rbDone) return;
  s.pr.getPacketHandler().writeNoCache(new @ARB@());
  s.rbDone = true;
  s.rbAt = System.currentTimeMillis();
  if (SESS.get(s.uuid) == s) flag(s.pr);
  info("minimap: " + s.who + "'s minimap pictures + the one picture rebuild sent " + when + " (hud:assets:ready set)");
}""")
# the player's world thread (MmRebuild): no custom page open = the rebuild goes now; a page open = it waits (the client repacks its UI
# texture atlas at a rebuild and an open page keeps pointing at stale atlas spots - Skyy's washed-out first-profile page, 2026-10-15)
MMM(mmmain, r"""
public static void rebuildCheck(@PKG@.MmSess s, @WLD@ w) {
  try {
    if (!s.rbDone && SESS.get(s.uuid) == s && s.pr != null && s.pr.isValid()) {
      @REF@ ref = s.pr.getReference();
      if (ref == null) rebuildSend(s, "between worlds (no page open)");
      else {
        @ST@ st = ref.isValid() ? ref.getStore() : null;
        @WLD@ here = null;
        try { here = st == null ? null : ((@ES@) st.getExternalData()).getWorld(); } catch (Throwable t) { here = null; }
        if (st == null || here != w) s.rbNext = System.currentTimeMillis() + 250L;
        else {
          @PLA@ p = (@PLA@) st.getComponent(ref, @PLA@.getComponentType());
          Object cp = null;
          if (p != null && p.getPageManager() != null) cp = p.getPageManager().getCustomPage();
          if (cp == null) rebuildSend(s, s.rbWaitLogged ? "after the open page closed" : "(no page open)");
          else {
            s.rbNext = System.currentTimeMillis() + 500L;
            if (!s.rbWaitLogged) {
              s.rbWaitLogged = true;
              info("minimap: " + s.who + " has a page open (" + cp.getClass().getSimpleName() + ") - the one picture rebuild waits until it is closed");
            }
          }
        }
      }
    }
  } catch (Throwable t) { s.rbNext = System.currentTimeMillis() + 1000L; err("the picture rebuild check", t); }
  s.rbAsk = false;
}""")
# the minimap thread: no entity in a world yet (connect: no page can exist) = write it now; else ONE check on the player's world thread
MMM(mmmain, r"""
public static void rebuild(@PKG@.MmSess s, long now) {
  if (s.rbAsk && now - s.rbAskAt > 3000L) s.rbAsk = false;     // review fix: the world stopped before the check ran - ask again
  if (s.rbDone || s.rbAsk || now < s.rbNext || s.pr == null) return;
  @REF@ ref = null;
  try { ref = s.pr.getReference(); } catch (Throwable t) { ref = null; }
  if (ref == null) { rebuildSend(s, "at connect, before the player is in a world"); return; }
  @WLD@ w = null;
  try { java.util.UUID wu = s.pr.getWorldUuid(); w = wu == null ? null : @UNI@.get().getWorld(wu); } catch (Throwable t) { w = null; }
  if (w == null) { s.rbNext = now + 250L; return; }
  s.rbAsk = true;
  s.rbAskAt = now;
  try { w.execute(new @PKG@.MmRebuild(s, w)); }
  catch (Throwable t) { s.rbAsk = false; s.rbNext = now + 1000L; err("reaching the world thread for the picture rebuild", t); }
}""")
# the 14 masks (7 sizes x round / square) + 16 arrows + the "not yet" picture go ONCE per connection, then ONE rebuild (critic C14)
# 0.3.27: sent at connect (the "hello" request) and the rebuild through rebuild() - never while a custom page is open
MMM(mmmain, r"""
public static void statics(@PKG@.MmSess s) {
  if (!STATICS.contains(s.uuid)) {
    for (int z = 50; z <= 200; z = z + 25) {
      int S = 160 * z / 100;
      int C = S - 2 * Math.max(3, S / 40);
      send(s, gen("mask:" + C + ":0"), false);
      send(s, gen("mask:" + C + ":1"), false);
    }
    for (int k = 0; k < 16; k++) send(s, gen("arrow:" + k), false);
    for (int k = 0; k < 16; k++) send(s, gen("arrowS:" + k), false);
    send(s, gen("dark"), false);
    STATICS.add(s.uuid);
  }
  rebuild(s, System.currentTimeMillis());
}""")''')

# ================================================================================================ handle: the "hello" request (minimap thread)
rep('''  if (@PKG@.MmCfg.BM != 1) return;
  if (r.kind.equals("ready")) {''', '''  if (@PKG@.MmCfg.BM != 1) return;
  // 0.3.27: PlayerConnectEvent's request - this connection's statics + the one rebuild NOW, before anything can open a page
  if (r.kind.equals("hello")) {
    @PKG@.MmSess h = (@PKG@.MmSess) SESS.get(r.uuid);
    if (h == null || h.pr != r.pr || !r.pr.isValid()) return;
    own(h);
    if (@PKG@.MmCfg.ENABLED) statics(h);
    return;
  }
  if (r.kind.equals("ready")) {''')

# ================================================================================================ attach: no HUD before the rebuild went (review fix)
# a rebuild still waiting (a page open when the minimap is switched on in Server Setup) = no HUD yet: it would point at masks the client has
# not repacked; pending (the "no stream yet" wait, its log flag untouched) makes step() re-run attach once the rebuild went
rep('''  geometry(s, l);
  statics(s);
  pictures(s);
''', '''  geometry(s, l);
  statics(s);
  if (!s.rbDone) { s.pending = true; s.pendingSince = now; return; }     // 0.3.27 review fix: the rebuild first, then the HUD
  pictures(s);
''')

# ================================================================================================ step: a waiting rebuild is re-checked every tick (0.5 s apart)
rep('''  if (pr == null || !pr.isValid()) { drop(s); return; }
  own(s);
  drain(s);
''', '''  if (pr == null || !pr.isValid()) { drop(s); return; }
  own(s);
  drain(s);
  if (!s.rbDone && STATICS.contains(s.uuid)) rebuild(s, now);     // 0.3.27: a rebuild waiting for a closed page / the world thread
''')

# ================================================================================================ hello / quit / shutdown
rep('''public static void hello(@PR@ pr) {
  if (pr == null) return;
  if (@PKG@.MmCfg.BM == 0) checkBM();
  if (@PKG@.MmCfg.BM != 1) return;
  sess(pr);
  recountTaps();
  ensureExec();
}''', '''public static void hello(@PR@ pr) {
  if (pr == null) return;
  unflag(pr.getUuid());
  if (@PKG@.MmCfg.BM == 0) checkBM();
  if (@PKG@.MmCfg.BM != 1 || !@PKG@.MmCfg.ENABLED) flag(pr);
  if (@PKG@.MmCfg.BM != 1) return;
  sess(pr);
  recountTaps();
  if (@PKG@.MmCfg.ENABLED) submit(new @PKG@.MmReq("hello", pr, null, null));
  ensureExec();
}''')
rep('''public static void quit(@PR@ pr) {
  if (pr == null || EXEC == null) return;''', '''public static void quit(@PR@ pr) {
  unflagFor(pr);
  if (pr == null || EXEC == null) return;''')
rep('''  try { if (e != null) e.shutdownNow(); } catch (Throwable t) { }
  synchronized (LOCK) { shutdown0(); }
}""")''', '''  try { if (e != null) e.shutdownNow(); } catch (Throwable t) { }
  synchronized (LOCK) { shutdown0(); }
  unflagAll();
}""")''')
rep('''# PlayerConnectEvent (before the first world's map burst): the session exists early, so the tap keeps the burst's keys
''', '''# PlayerConnectEvent (before the first world's map burst): the session exists early, so the tap keeps the burst's keys
# 0.3.27: + a NEW connection starts unflagged; no minimap pictures will come (BetterMap missing / minimap off in Server Setup) = flagged at
# once; else the "hello" request sends the statics + the one rebuild on the minimap thread right away (before any page can open)
''')

# ================================================================================================ MmRebuild.run (the small bodies)
rep('''MMM(mmdet, "public void run() { @PKG@.Minimap.detachNow(this.pr, this.store, this.hud); }")
''', '''MMM(mmdet, "public void run() { @PKG@.Minimap.detachNow(this.pr, this.store, this.hud); }")
MMM(mmreb, "public void run() { @PKG@.Minimap.rebuildCheck(this.sess, this.world); }")
''')

# ================================================================================================ checks on the result
assert s.count("writeNoCache(new @ARB@())") == 1, "one rebuild write (rebuildSend)"
_i = s.index
assert _i("public static void flag(@PR@ pr)") < _i("public static void rebuildSend(") < _i("public static void rebuildCheck(") < _i("public static void rebuild(@PKG@.MmSess s, long now)") < _i("public static void statics(@PKG@.MmSess s)") < _i("public static void handle(@PKG@.MmReq r, long now)")
assert _i('MMC(mmreb, "public MmRebuild(') < _i("public static void rebuild(@PKG@.MmSess s, long now)") < _i('MMM(mmreb, "public void run()')
assert _i("public static void unflagAll()") < _i("public static void shutdown()")

# ================================================================================================ done
_u = s
for _new, _old in reversed(CHANGES):
    assert _u.count(_new) == 1, "a change is not unique any more: %s" % _new[:100]
    _u = _u.replace(_new, _old, 1)
assert _u == OLD, "the generated script differs from 0.3.26 outside the recorded changes"
compile(s, dst, "exec")
open(dst, "w", encoding="utf8", newline="").write(s.replace(LF, NL) if NL != LF else s)
print("wrote", os.path.relpath(dst, ROOT), "(%d lines; 0.3.26 had %d; %d changes)" % (s.count(LF), OLD.count(LF), len(CHANGES)))
